import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken(); int n = (int) in.nval;
        int[] c = new int[n];
        for (int i = 0; i < n; i++) { in.nextToken(); c[i] = (int) in.nval; }
        Arrays.sort(c);   // ascending; walk from the end for descending order
        int h = 0;
        for (int i = 0; i < n; i++) {
            int cites = c[n - 1 - i];           // (i+1)-th most cited paper
            if (cites >= i + 1) h = i + 1;
            else break;
        }
        System.out.println(h);
    }
}

